src/ua_types.c","function":"UA_copy","line":960,"var":"dst","code":"UA_clear(dst, type);","role":"intermediate","note":"UA_copy sees bad retval from copy_noInit and calls UA_clear on dst, which calls clear_noInit"},{"step":8,"file":"src/ua_types.c","function":"DataValue_clear","line":799,"var":"p->value","code":"Variant_clear(&p->value, NULL);","role":"sink","note":"Second DataValue_clear is called via clear_noInit; Variant_clear reads p->value.type and p->value.data which are dangling pointers to already-freed memory - heap-use-after-free READ 4"}],"vuln_logic":{"source":{"file":"tests/fuzz/fuzz_binary_decode.cc","function":"tortureEncoding","line":34,"operands":["dst","data"]},"root_cause":{"file":"src/ua_types.c","function":"Variant_copy","line":428,"operands":["dst->arrayDimensions","memoryLimit"],"relation":{"op":"le","left":"totalMemorySize + size","right":"memoryLimit"}},"sink":{"file":"src/ua_types.c","function":"DataValue_clear","line":799,"operands":["p->value.type","p->value.data"],"relation":{"op":"ne","left":"p->value.data","right":"NULL"}},"propagation":[{"from":{"file":"tests/fuzz/fuzz_binary_decode.cc","function":"tortureEncoding","line":34,"operands":["dst"]},"to":{"file":"src/ua_types.c","function":"Variant_copy","line":421,"operands":["dst->data"]},"type":"data","via":["UA_copy","copy_noInit","DataValue_copy","Variant_copy"]},{"from":{"file":"src/ua_types.c","function":"Variant_copy","line":428,"operands":["retval"]},"to":{"file":"src/ua_types.c","function":"DataValue_copy","line":810,"operands":["dst"]},"type":"control","via":["retval != UA_STATUSCODE_GOOD"]},{"from":{"file":"src/ua_types.c","function":"Variant_clear","line":410,"operands":["p->data"]},"to":{"file":"src/ua_types.c","function":"DataValue_clear","line":799,"operands":["p->value"]},"type":"data","via":["p->value.data","p->value.type"],"relation":{"op":"ne","left":"p->value.data","right":"NULL"}}]}}
